output_text:
[
  {
    "id": "entry_cart_required",
    "text": "Customers must take the stationed entry cart before continuing their shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "no_cartless_item_pickup",
    "text": "Items should not be taken from shelves unless the customer currently has a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        },
        "hand_carrying": "handFull"
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": "hand_carrying"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "cart_return_bay_only",
    "text": "A cart may only be put down at the top-left return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "away_from_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "cart_put_down": {
          "pre": "LEAVE_CART",
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_put_down",
          "away_from_cart_return_bay"
        ]
      }
    }
  },
  {
    "id": "return_cart_if_at_service_with_cart",
    "text": "If a customer reaches the top-left service point while pushing a cart, they must leave the cart there before exiting.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "at_service_with_cart": {
          "and": [
            "top_left_service_point",
            "hasCart"
          ]
        },
        "service_cart_waiting": "cartAt(0,1)",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "service_cart_return": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_cart_waiting",
              "cartless"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_service_with_cart",
      "discharge": "service_cart_return"
    }
  },
  {
    "id": "do_not_reclaim_returned_service_cart",
    "text": "Once a cart has been returned to the top-left service bay, it should not be picked up again.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": "cartAt(0,1)",
        "returned_cart_available": {
          "and": [
            "top_left_service_point",
            "service_cart_waiting"
          ]
        }
      },
      "events": {
        "returned_service_cart_reclaimed": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "returned_service_cart_reclaimed"
    }
  },
  {
    "id": "depart_service_south_cartless",
    "text": "After returning a cart at the top-left service point, the customer must leave that point to the south without the cart.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": "cartAt(0,1)",
        "cartless": {
          "not": "hasCart"
        },
        "at_service_with_cart": {
          "and": [
            "top_left_service_point",
            "hasCart"
          ]
        },
        "at_service_cartless_with_cart_waiting": {
          "and": [
            "top_left_service_point",
            "cartless",
            "service_cart_waiting"
          ]
        }
      },
      "events": {
        "service_cart_return": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_cart_waiting",
              "cartless"
            ]
          }
        },
        "south_departure_without_cart": {
          "pre": {
            "and": [
              "at_service_cartless_with_cart_waiting",
              "S"
            ]
          },
          "post": {
            "and": [
              "at(0,2)",
              "service_cart_waiting",
              "cartless"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_cart_return",
      "discharge": "south_departure_without_cart"
    }
  },
  {
    "id": "no_cart_in_upper_right_cell",
    "text": "Customers must not push a cart into the upper-right restricted cell at coordinate (8,2).",
    "abstraction": {
      "state_properties": {
        "upper_right_restricted_cell": "at(8,2)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_enters_upper_right_restricted_cell": {
          "pre": {
            "and": [
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "upper_right_restricted_cell",
              "pushing_cart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_enters_upper_right_restricted_cell",
          {
            "and": [
              "upper_right_restricted_cell",
              "pushing_cart",
              "MOVE"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "temporary_service_check_requires_reclaim",
    "text": "A cart left at the top-left service point for a service check must be picked back up before the customer exits.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": "cartAt(0,1)",
        "cartless": {
          "not": "hasCart"
        },
        "at_service_with_cart": {
          "and": [
            "top_left_service_point",
            "hasCart"
          ]
        },
        "returned_cart_available": {
          "and": [
            "top_left_service_point",
            "service_cart_waiting",
            "cartless"
          ]
        }
      },
      "events": {
        "temporary_service_drop": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_cart_waiting",
              "cartless"
            ]
          }
        },
        "service_cart_reclaimed": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_service_drop",
      "discharge": "service_cart_reclaimed"
    }
  }
]
